tokens:
--scheme: light;
color-scheme: light;
--bg: #eef0f8;
--bg2: #e7e8f5;
--surface: #ffffff;
--surface2: #e4e5f3;
--ink: #14163a;
--muted: #33375f;
--faint: #4d5280;
--cardmeta: #23264d;
--gold: #5b33c4;
--gold-soft: #4a28a6;
--gold-deep: #14163a;
--on-gold: #ffffff;
--ink-soft: #33375f;
--line: rgba(20, 22, 58, 0.16);
--line-strong: #5b33c4;
--ok: #1f6b33;
--warn: #7f5800;
--bad: #b0220f;
--shadow: 0 1px 2px rgba(60, 50, 140, 0.10), 0 8px 22px rgba(60, 50, 140, 0.12);
--elev-1: 0 1px 2px rgba(60, 50, 140, 0.10), 0 3px 10px rgba(60, 50, 140, 0.08);
--elev-2: 0 2px 4px rgba(60, 50, 140, 0.10), 0 12px 28px rgba(60, 50, 140, 0.14);
--elev-3: 0 4px 10px rgba(60, 50, 140, 0.12), 0 28px 70px rgba(60, 50, 140, 0.22);
--scrim: rgba(20, 22, 58, 0.40);
--focus: #2f6fd6;
--th-bg: #e4e5f3;
--tabgrad1: #e4e5f3; --tabgrad2: #ffffff;
--toastgrad1: #e4e5f3; --toastgrad2: #ffffff;
--foot-bg: rgba(238, 240, 248, 0.94);
--drawerbar-bg: rgba(255, 255, 255, 0.96);
--ph-bg: #e4e5f3;
--sel-bg: rgba(91, 51, 196, 0.16);
--row-hover: rgba(91, 51, 196, 0.07);
--hold-bg: linear-gradient(135deg, #e4e5f3, #ffffff);
--skeleton1: #e4e5f3; --skeleton2: #eef0f8;
--grain-op: 0.02;
--wing-dur: 0.4s;
--wing-rise: 12px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, -apple-system, sans-serif;
--radius: 18px;
--y2k-pink: #f6b8e4;
--y2k-sky: #b9d4ff;
--y2k-lilac: #d6c8ff;
/* the dark display-case interior used by the instrument panels (styles/style-layer.css, ui "paper"): deep navy chrome */
--case-bg: #14163a;
--case-bg2: #1b1e4a;
--case-surface: #20245a;
--case-surface2: #2b3070;
--case-ink: #ffffff;
--case-muted: #d8dcff;
--case-faint: #b4baf0;
--case-gold: #c9b8ff;
--case-gold-soft: #e6dcff;
--case-on-gold: #14163a;
/* the page palette again, for paper labels inside a case */
--paper-bg: #eef0f8;
--paper-bg2: #e7e8f5;
--paper-surface: #ffffff;
--paper-surface2: #e4e5f3;
--paper-ink: #14163a;
--paper-muted: #33375f;
--paper-faint: #4d5280;
--paper-gold: #5b33c4;
--paper-gold-soft: #4a28a6;
--paper-on-gold: #ffffff;

